/// Number of individual (predefined) LWLocks = last lockidx + 1.
///
/// Mirrors `lwlocknames.h`'s `#define NUM_INDIVIDUAL_LWLOCKS`.  The last entry
/// in lwlocklist.h is `PG_LWLOCK(53, AioWorkerSubmissionQueue)`, so this is 54.
/// Note this counts the skipped/gap indices too: it is the size of the
/// individual-lock region of `MainLWLockArray`, not the number of live locks.
pub const NUM_INDIVIDUAL_LWLOCKS: c_int = 54;

/// One row of the materialized lwlocklist projection: a predefined LWLock's
/// index within `MainLWLockArray` and its human-facing name (with the "Lock"
/// suffix the C code appends, matching `lwlocknames.h` / wait-event reporting).
#[derive(Clone, Copy, Debug)]
pub struct LWLockName {
    /// The lockidx (index into the individual-lock region of MainLWLockArray).
    pub id: c_int,
    /// The display name with the "Lock" suffix, e.g. "ShmemIndexLock".
    pub name: &'static str,
}

/// The predefined LWLock list, verbatim from storage/lwlocklist.h (only the
/// live entries - removed/gap indices are omitted, as they have no name).
/// Ordered by index.  This is the data `generate-lwlocknames.pl` consumes.
